"""Benchmark tasks (Lueckmann et al. 2021 definitions) + reference posterior samplers."""
import math
import numpy as np
import torch
from scipy.linalg import block_diag


# ---------------------------------------------------------------- masks (addendum)
def mask_gaussian_linear():
    M_tt = np.eye(10); M_xx = np.eye(10); Z = np.zeros((10, 10)); M_tx = np.eye(10)
    return np.block([[M_tt, Z], [M_tx, M_xx]]).astype(bool)


def mask_two_moons_gmm(dx=2):
    # addendum lists a 10x10 x-block (typo); task has 2-dim data -> use tril(dx)
    M_tt = np.eye(2); M_xx = np.tril(np.ones((dx, dx))); Z = np.zeros((2, dx)); M_tx = np.ones((dx, 2))
    return np.block([[M_tt, Z], [M_tx, M_xx]]).astype(bool)


def mask_slcp():
    # SLCP has 5 parameters and 4 iid 2d observations
    M_tt = np.eye(5)
    M_xx = block_diag(*[np.tril(np.ones((2, 2))) for _ in range(4)])
    Z = np.zeros((5, 8)); M_tx = np.ones((8, 5))
    return np.block([[M_tt, Z], [M_tx, M_xx]]).astype(bool)


# ---------------------------------------------------------------- tasks
class Task:
    name = ""
    dim_theta = 0
    dim_x = 0

    def prior_sample(self, n):
        raise NotImplementedError

    def simulate(self, theta):
        raise NotImplementedError

    def joint(self, n):
        th = self.prior_sample(n)
        return th, self.simulate(th)


class GaussianLinear(Task):
    name = "gaussian_linear"; dim_theta = 10; dim_x = 10
    def prior_sample(self, n): return torch.randn(n, 10) * math.sqrt(0.1)
    def simulate(self, th): return th + torch.randn_like(th) * math.sqrt(0.1)
    def mask(self): return mask_gaussian_linear()
    def reference_posterior(self, x, n):
        # prior N(0, .1), lik N(theta, .1) -> post N(x/2, .05)
        return x / 2 + torch.randn(n, 10) * math.sqrt(0.05)


class GaussianMixture(Task):
    name = "gaussian_mixture"; dim_theta = 2; dim_x = 2
    def prior_sample(self, n): return torch.rand(n, 2) * 20 - 10
    def simulate(self, th):
        scale = torch.where(torch.rand(th.shape[0], 1) < 0.5, 1.0, 0.1)
        return th + torch.randn_like(th) * scale
    def mask(self): return mask_two_moons_gmm(2)
    def reference_posterior(self, x, n):
        out = []
        while sum(len(o) for o in out) < n:
            m = 4 * n
            scale = torch.where(torch.rand(m, 1) < 0.5, 1.0, 0.1)
            s = x + torch.randn(m, 2) * scale
            s = s[(s.abs() <= 10).all(1)]
            out.append(s)
        return torch.cat(out)[:n]


class TwoMoons(Task):
    name = "two_moons"; dim_theta = 2; dim_x = 2
    def prior_sample(self, n): return torch.rand(n, 2) * 2 - 1
    def simulate(self, th):
        n = th.shape[0]
        a = (torch.rand(n) - 0.5) * math.pi
        r = 0.1 + 0.01 * torch.randn(n)
        p = torch.stack([r * torch.cos(a) + 0.25, r * torch.sin(a)], 1)
        z0 = -(th[:, 0] + th[:, 1]).abs() / math.sqrt(2)
        z1 = (-th[:, 0] + th[:, 1]) / math.sqrt(2)
        return p + torch.stack([z0, z1], 1)
    def mask(self): return mask_two_moons_gmm(2)
    def log_lik(self, th, x):
        z0 = -(th[:, 0] + th[:, 1]).abs() / math.sqrt(2)
        z1 = (-th[:, 0] + th[:, 1]) / math.sqrt(2)
        p = x - torch.stack([z0, z1], 1)
        u = p[:, 0] - 0.25; v = p[:, 1]
        r = torch.sqrt(u ** 2 + v ** 2)
        ll = -0.5 * ((r - 0.1) / 0.01) ** 2 - torch.log(r)
        return torch.where(u > 0, ll, torch.full_like(ll, -float("inf")))
    def reference_posterior(self, x, n):
        return sir(lambda m: self.prior_sample(m), lambda th: self.log_lik(th, x), n, n_prop=20_000_000)


class SLCP(Task):
    name = "slcp"; dim_theta = 5; dim_x = 8
    def prior_sample(self, n): return torch.rand(n, 5) * 6 - 3
    def _musig(self, th):
        mu = th[:, :2]
        s1 = th[:, 2] ** 2; s2 = th[:, 3] ** 2; rho = torch.tanh(th[:, 4])
        S = torch.stack([torch.stack([s1 ** 2, rho * s1 * s2], -1),
                         torch.stack([rho * s1 * s2, s2 ** 2], -1)], -2) + 1e-6 * torch.eye(2)
        return mu, S
    def simulate(self, th):
        mu, S = self._musig(th)
        d = torch.distributions.MultivariateNormal(mu, covariance_matrix=S)
        return d.sample((4,)).permute(1, 0, 2).reshape(-1, 8)
    def mask(self): return mask_slcp()
    def log_lik(self, th, x):
        mu, S = self._musig(th)
        d = torch.distributions.MultivariateNormal(mu, covariance_matrix=S)
        xs = x.reshape(4, 2)
        return sum(d.log_prob(xs[i].expand(th.shape[0], 2)) for i in range(4))
    def log_post(self, th, x):
        inb = (th.abs() <= 3).all(1)
        th_c = th.clamp(-3, 3)
        lp = self.log_lik(th_c, x)
        return torch.where(inb, lp, torch.full_like(lp, -float("inf")))
    def reference_posterior(self, x, n):
        init = sir(lambda m: self.prior_sample(m), lambda th: self.log_lik(th, x), n, n_prop=4_000_000)
        return mh(lambda th: self.log_post(th, x), init, steps=2000, step=0.05)


TASKS = {c.name: c for c in [GaussianLinear, GaussianMixture, TwoMoons, SLCP]}


# ---------------------------------------------------------------- reference samplers
@torch.no_grad()
def sir(prior, loglik, n, n_prop=1_000_000, chunk=1_000_000):
    ths, lls = [], []
    for _ in range(max(1, n_prop // chunk)):
        th = prior(chunk); ll = loglik(th)
        keep = ll > -1e30
        ths.append(th[keep]); lls.append(ll[keep])
    th = torch.cat(ths); ll = torch.cat(lls).double()
    w = torch.softmax(ll, 0)
    idx = torch.multinomial(w.float(), n, replacement=True)
    return th[idx]


@torch.no_grad()
def mh(logp, init, steps=1000, step=0.05):
    th = init.clone(); lp = logp(th)
    for _ in range(steps):
        prop = th + step * torch.randn_like(th)
        lpp = logp(prop)
        acc = torch.log(torch.rand(len(th))) < (lpp - lp)
        th[acc] = prop[acc]; lp[acc] = lpp[acc]
    return th
